package com.sistemahospitalar.hospital.controller; import com.sistemahospitalar.hospital.model.Paciente; import com.sistemahospitalar.hospital.service.PacienteService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/pacientes") public class PacienteController {private final PacienteService service; public PacienteController(PacienteService s){service=s;} @GetMapping public List<Paciente> listar(){return service.listar();} @GetMapping("/{id}") public Paciente buscar(@PathVariable Long id){return service.buscar(id);} @PostMapping public ResponseEntity<Paciente> criar(@Valid @RequestBody Paciente p){return ResponseEntity.status(HttpStatus.CREATED).body(service.salvar(p));} }
